"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4771],{5919:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"CannonConfig","desc":"Tuning for the train-mounted Cannon (tier 1: one barrel, medium fire rate,\\nsmall blast). Same fields as `AutoCannonConfig`: it runs on the shared\\nshell-turret code (`ShellTurretServer`, `TrainTurret/ShellWeapon`,\\n`BurstCannonMath`). `BurstSize = 1` makes every shot its own burst, so the\\ncadence is one shot every `BurstPause`. All sound keys resolve through\\nSoundManager/SoundConfig. Angles in degrees unless the name says otherwise.\\n\\nSome constants here are shared by every train turret (Smart Cannon idle time\\nand range, the `EnemyShip` tag); other modules read them from this config.","source":{"line":15,"path":"src/ReplicatedStorage/SharedModules/Configs/CannonConfig.luau"}}')}}]);